<?php declare(strict_types=1);define('PROJECT_ROOT',dirname(__DIR__,2));require PROJECT_ROOT.'/vendor/autoload.php';require_once PROJECT_ROOT.'/core/Storage.php';use App\Services\Ledger\TaxFinancialStatementService;use Core\DbPdo;$db=DbPdo::conn();$c=(string)$db->query('SELECT id FROM system_company LIMIT 1')->fetchColumn();$u=(string)$db->query('SELECT id FROM auth_users LIMIT 1')->fetchColumn();$a=(string)$db->query('SELECT id FROM ledger_accounts WHERE deleted_at IS NULL AND is_posting=1 LIMIT 1')->fetchColumn();if(session_status()!==PHP_SESSION_ACTIVE)session_start();$_SESSION['user']=['id'=>$u];$_SESSION['auth_state']=['user_id'=>$u,'status'=>'NORMAL'];$before=[(int)$db->query('SELECT COUNT(*) FROM ledger_tax_financial_statements')->fetchColumn(),(int)$db->query('SELECT COUNT(*) FROM ledger_tax_financial_statement_lines')->fetchColumn()];$db->beginTransaction();try{$s=new TaxFinancialStatementService($db);$r=$s->save(['company_id'=>$c,'fiscal_year'=>2996,'report_type_code'=>'INCOME_STATEMENT','source_organization'=>'회귀검증 세무법인','filing_date'=>'2997-03-31','lines'=>[['item_code'=>'TEST','item_name'=>'회귀검증 과목','account_id'=>$a,'hierarchy_level'=>1,'current_amount'=>1000,'prior_amount'=>900]]]);$id=$r['data']['id'];$s->confirm($id,true);$x=$s->comparison($c,2996,'INCOME_STATEMENT');if(count($x['rows'])!==1||$x['document']['status_code']!=='CONFIRMED')throw new RuntimeException('확정 또는 비교에 실패했습니다.');$s->confirm($id,false);$s->delete($id);$db->rollBack();$after=[(int)$db->query('SELECT COUNT(*) FROM ledger_tax_financial_statements')->fetchColumn(),(int)$db->query('SELECT COUNT(*) FROM ledger_tax_financial_statement_lines')->fetchColumn()];$ok=$before===$after;echo json_encode(['success'=>$ok,'save'=>'PASS','confirm'=>'PASS','comparison'=>'PASS','cancel_confirm'=>'PASS','delete'=>'PASS','rollback'=>$ok?'PASS':'FAIL'],JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT);exit($ok?0:1);}catch(Throwable$e){if($db->inTransaction())$db->rollBack();fwrite(STDERR,$e->getMessage().PHP_EOL.$e->getTraceAsString());exit(1);}
